/* AUTO-GENERATED by tools/build-faq-kb.js — do not hand-edit; run: node tools/build-faq-kb.js
   Haus Helper knowledge base: harvested FAQs/TIPS from the Hausen +
   template FAQ blocks + curated common answers. Regenerate to refresh. */
window.P2P_FAQ_KB = [{"q":"What does the \"Include in prompt\" checkbox do?","a":"It controls whether that field's value actually lands in your final prompt. Uncheck it to exclude a selection without clearing the dropdown.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Why did some of my selections change when I clicked Randomize?","a":"Randomize only touches fields with \"Include in prompt\" checked — anything you've unchecked is left alone.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What does Reset actually clear?","a":"That mode's own fields, plus Holiday/Creative Theme/Niche/Target Audience/Mood, Filter, Imagery, and Negative Prompt. Buffer/Padding and the format settings (Project Type, Aspect Ratio, Target Platform, Variations) are left as you set them.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What's the difference between Core Style and Variation Details in Text Mode?","a":"Core Style stays the same across every variation the AI generates. Variation Details are what the AI is free to change between them.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Why does my copied prompt look different depending on Target Platform?","a":"Different AI tools read prompts differently — Midjourney wants tag-style keywords, ChatGPT (GPT Image) reads better as full sentences. Target Platform reformats your prompt automatically for whichever you pick.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"How many prompts can I save?","a":"Up to 5 saved prompts per mode in Your Vault.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Does my uploaded reference photo get saved or sent anywhere?","a":"No. It stays in your browser as a visual reference for you and is never uploaded, stored, or analyzed anywhere.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What if a dropdown doesn't have the exact option I want?","a":"Use the \"Or type your own...\" field under any dropdown — it always overrides the dropdown selection.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What does Buffer/Padding do?","a":"Asks the AI to leave empty space around the edges of the image so nothing important gets cropped off during printing or cropping.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Can I combine Character, Text, and Graphics into one image?","a":"Yes — that's what Combined Mode is for. It builds one cohesive prompt from all three instead of three separate ones.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"How do I make one word or phrase look different from the rest of my text?","a":"Use Second Phrase in Text Mode (or Add Text in other modes) to give a word or phrase its own separate styling and position.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Why does Aspect Ratio change when I change Project Type?","a":"It auto-suggests a sensible ratio for that product. You can still override it manually any time — it'll stop following Project Type once you do.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What's the Imagery section for?","a":"Small symbolic elements — a cross, a holiday icon, a military emblem, a nature/sci-fi/fantasy element — woven into the image. Pick up to 4 total across the categories. Every mode has it.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Will my saved prompts still be there if I close my browser?","a":"Yes, on the same device and browser — Your Vault is saved locally. It won't carry over to a different device or browser.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Can I turn a real photo into an illustration style?","a":"Yes — in Image/Prompt Reference Mode, upload or describe your photo, then use Style Adjustment (Reimagined Style + Art Finish) to recreate it in a different style, like watercolor or chibi.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"I found a prompt someone else wrote — will it just get copied if I paste it in?","a":"No. Switch Image/Prompt Reference Mode to \"Reference a Prompt\" and paste it there — the assembled prompt explicitly tells the AI to use it only as loose creative direction and produce an original result, not reuse the wording. Pick your own Reimagined Style/Art Finish on top for an even more distinct result.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Why is Filter now inside each mode's Style section instead of the top bar?","a":"It's a rendering/finish choice, like Art Finish — grouping it with the rest of the mode's style controls makes it easier to find.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"My Image/Prompt Reference description fights with the style I picked — why, and what fixes it?","a":"If your description was reverse-engineered from a real photo (through ChatGPT or a similar tool), it's usually full of photographic/camera language. Once you pick a Reimagined Style, the prompt automatically tells the AI to replace any photographic qualities in the description with that style — you don't need to edit the description yourself.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What is Brand Kit (\"My HAUS Style\")?","a":"A saved set of your brand's colors, fonts, visual style, and personality — collapsible under Your Vault. Activate one and every mode auto-inherits it instead of you re-picking your brand each time. Up to 3 kits, only one active at a time, and each has a per-category override so you can keep your own picks for just one category on a specific project without turning the whole kit off.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Does Brand Kit work the same as Your Vault?","a":"Same persistence (saved locally in your browser) and the same Share/Copy/Download/Print export, but a different job — Vault saves finished prompts, Brand Kit saves a reusable identity that feeds into prompts you haven't built yet.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What does Negative Prompt do?","a":"One shared \"what to avoid\" field at the top of the tool, applied to every mode — formatted as --no tags for Midjourney/Leonardo, or an \"Avoid:\" sentence for everything else. Brand Kit's \"What the Brand is NOT\" merges into this same list automatically.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Can I get a saved prompt back into the builder to keep editing it?","a":"Yes — click Load on any item in Your Vault. It restores every field to exactly how it was when you saved it, across every mode that prompt used (including Character/Text/Graphics all at once for a saved Combined prompt).","haus":"Content Haus","url":"/pages/content-haus"},{"q":"How many people can I add in Friends & Family?","a":"Up to 5 adults and up to 5 kids, in any mix — a single adult with kids, a full household, a friend group with no kids at all, whatever fits. Each person has their own Remove button, so taking one out doesn't mean redoing the others.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Can I add more than one companion/pet?","a":"Yes — Character, Couples, and Friends & Family all support up to 3 companions in a shared pool (e.g. 2 dogs and a cat), not just one. Each has its own Remove button too.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What's the difference between Collection Builder's \"Combine Prompts\" and Combined Mode?","a":"Combined Mode builds one unified image brief where Character/Text/Graphics share a single scene from scratch. Collection Builder's Combine Prompts instead takes prompts you've already built separately on other tabs and splices their finished text together — useful when you want each piece's own independent output stitched into one block, not one shared composition.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (1)","a":"Pick ONE core style rather than stacking several — mixing chibi with photorealistic, for example, gives the AI conflicting instructions instead of a clearer one.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (2)","a":"Less is more. A focused handful of specific choices reads better to the AI than maxing out every single field.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (3)","a":"\"Or type your own...\" always overrides the dropdown — use it for anything hyper-specific the options don't cover.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (4)","a":"Set Target Platform before you copy — it reformats the prompt to match how that AI tool reads best (tags for Midjourney, plain sentences for ChatGPT, etc.).","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (5)","a":"Stuck? Hit Randomize, then swap out just the 1-2 things you don't love instead of starting over from scratch.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (6)","a":"Save combinations you like to Your Vault so you can revisit and tweak them later instead of rebuilding from memory.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (7)","a":"Set up a Brand Kit once — colors, fonts, and style — and every mode inherits it automatically instead of you re-picking your brand every time.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (8)","a":"Use Negative Prompt to head off known AI mistakes (extra fingers, watermarks, blurry text) before they happen, not after you've already generated something.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"Tip for better prompts (9)","a":"Building a group in Friends & Family? Add everyone first, then dial in the Dynamic — that way the vibe/pose you pick actually fits who's in the shot.","haus":"Content Haus","url":"/pages/content-haus"},{"q":"What is The Archetype Guide, and do I have to start there?","a":"The Archetype Guide is the very first thing you'll see — a chance to click through all 11 Brand DNA Archetypes and get a feel for each one before you answer a single question, so you know what you're working toward. It's just a preview, not a quiz — nothing you click there affects your actual result, and you can always revisit it later from the sidebar.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"Why should I take the Brand DNA Assessment?","a":"Most brand quizzes hand you a generic label and call it done. The Brand DNA Assessment is built on our own framework — 8 Brand Tensions, not borrowed archetype tropes — so what comes back is a real reflection of how you already think, what you value, and what's already showing up in your work whether you've named it or not. It's the foundation everything else in the Brand Haus builds on: your colors, fonts, mission, and voice all trace back to this one result.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"What kind of questions does it ask?","a":"A guided, 30-question conversation — not multiple-choice trivia. You'll be asked how you naturally make decisions, what you value in how you work, and what you want people to feel when they experience your brand. There are no right answers; every answer just sharpens the picture.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"How is this different from a typical brand archetype quiz?","a":"Two things. First, our 11 Brand DNA profiles aren't the standard 12 Jungian archetypes recycled again — they're built from real founder patterns, including ones (like The Trail Forger) added specifically because the standard set didn't cover them. Second, you don't just get a label: you get a real percentage showing how strongly you match, which other profiles are quietly influencing you, and a personalized blend — not a one-size-fits-all page.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"What do I actually get with the Brand Haus?","a":"Your match unlocks a one-page Blueprint Snapshot, a Comprehensive Report, and a 19-guide Brand Playbook covering your tensions, your ideal customer's experience, your visual identity, and your next steps. From there, Find Your Direction helps you turn that result into a real next move; Branding Studio turns it into real colors, fonts, and mission language; Logo Studio builds your mark; and Quick Generators produce ready-to-use assets like a Business Card Kit and Media Kit — all pulling from the same real result, nothing re-typed from scratch.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"What is Find Your Direction, and is it required?","a":"Find Your Direction is a short, optional intake that sits right before Branding Studio. It asks a handful of questions tailored to one of two paths — building your own personal brand as a creator/influencer, or building a brand around a specific niche product idea — and turns your answers into a ready-to-paste brief for Frank, your AI Business Partner in the Idea Haus, so you can start a real back-and-forth about what to actually build. It doesn't change your Blueprint or gate anything else in the Brand Haus — skip it any time and come back to it later from the sidebar.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"Who is Frank, and how do I talk to him?","a":"Frank is your AI Business Partner, living in a custom GPT called the Idea Haus. Your Brand Haus purchase includes access to him. Find Your Direction's brief is built specifically to hand to Frank — copy it, open the Idea Haus link on the completion screen, and paste it in to start the conversation.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"Do I have to pay again to keep using this?","a":"No — once you've purchased access to The Brand Haus, you have unlimited access to everything: the Brand DNA Assessment, Find Your Direction, Branding Studio, Logo Studio, and Quick Generators, with no extra fees.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"What should I do after I get my result?","a":"Start with your Blueprint Snapshot for the quick version. If you're still figuring out what to actually create, Find Your Direction can turn your result into a starting brief for Frank. From there, move into Branding Studio to lock in your colors, fonts, and mission — Logo Studio and Quick Generators turn that identity into things you can actually use.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"Can I retake it?","a":"Yes. Brands evolve, and your Brand DNA can shift as your business does. Retaking the assessment saves a new version automatically, and you can keep up to 3 full results side by side in your Saved Results vault — so you're never stuck choosing between starting over and losing what you had.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"What do I actually get afterward?","a":"Your match unlocks the full Brand Haus: a one-page Blueprint Snapshot, a Comprehensive Report, and a 19-guide Brand Playbook covering your tensions, your ideal customer's experience, your visual identity, and your next steps. From there, Branding Studio turns your result into real colors, fonts, and mission language; Logo Studio builds your mark; and Quick Generators produce ready-to-use assets like a Business Card Kit and Media Kit — all pulling from the same real result, nothing re-typed from scratch.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"Do I have to pay every time I want to use it?","a":"No, once you've purchased access to The Brand Haus you have unlimited access. You can browse all 11 Brand DNA Archetypes for free right here on this page, no assessment required. The full assessment, your personalized results, and everything in the Brand Haus (Branding Studio, Logo Studio, Quick Generators) come with Get Access, above.","haus":"Brand Haus","url":"/pages/brand-haus"},{"q":"How do I get started?","a":"Work top-to-bottom down your sidebar: take the Founders Assessment, lock your Brand DNA, then Content, Graphics, Project, Marketing, and launch with ROOTED. One step at a time.","haus":"Operating System","url":"/pages/p2p-os"},{"q":"Which Haus should I use?","a":"Brand Haus for your identity, Content Haus for words and prompts, Graphics Haus for visuals, Project Haus to build a product, Marketing Haus to promote it, Growth Haus to launch and scale.","haus":"Operating System","url":"/pages/p2p-os"},{"q":"What is ROOTED?","a":"ROOTED is your 6-stage launch method: Reach, Open, Offer, Trigger, Escalate, Deepen. It carries you from ready to launched, and the full course lives in the Evergreens realm.","haus":"Growth Haus","url":"/pages/p2p-os?v=rooted"},{"q":"Is this for me? Am I too non-technical?","a":"Purpose 2 Profit is built for creators and sellers who want to go from idea to income, especially if you are not techy. Everything is plain language, one step at a time. If you can follow a recipe, you can do this.","haus":"Operating System","url":"/pages/p2p-os"},{"q":"Who are Frank and Ruth (the Haus Mates)?","a":"Frank (Idea Haus) sparks and sharpens ideas; Ruth (Build Haus) makes them sellable. They are your AI partners, open either any time you are stuck.","haus":"Haus Mates","url":"/pages/p2p-os?v=mates"},{"q":"What is included in my plan / pricing?","a":"Each Haus is its own tool you can unlock, and the Learning Journey is the full step-by-step course path. For exactly what is in your plan and current pricing, the clearest answer is on that Haus's page, or just ask us.","haus":"Billing","url":null},{"q":"I can't log in / lost access","a":"A login or access hiccup is almost always a billing blip; updating your payment info usually restores access right away. If not, email us and we will sort it fast.","haus":"Billing","url":null},{"q":"Something isn't working (a bug or glitch)","a":"Quick fixes that solve most things: refresh the page, try a different browser, or sign out and back in; your progress is saved to your account, not the browser. Still stuck? Tell us what you were doing.","haus":"Billing","url":null},{"q":"How do I cancel or change my plan?","a":"You are always in control, no hoops. To cancel or change a plan, sign in to your account, or email us and we will take care of it for you.","haus":"Billing","url":null},{"q":"Where is the Learning Journey / courses?","a":"Your Learning Journey is the gamified course map: realms, courses and badges that teach the whole thing one step at a time.","haus":"Learning Journey","url":"/pages/p2p-learning"},{"q":"What does Graphics Haus do?","a":"Graphics Haus builds on-brand visuals and design prompts — clipart, characters, seasonal art, product graphics and more — so you can create a consistent look without a design degree.","haus":"Graphics Haus","url":"/pages/graphics-haus"},{"q":"Do I need design skills to use Graphics Haus?","a":"No. You make a few plain-language choices and Graphics Haus writes a detailed prompt you paste into any AI image tool. It handles the design language so you don't have to.","haus":"Graphics Haus","url":"/pages/graphics-haus"},{"q":"Will my graphics match my brand?","a":"Yes — set up your Brand Kit once (colors, fonts, style) and Graphics Haus pulls it in, so every visual comes out on-brand. Save a Look Lock to keep a set consistent.","haus":"Graphics Haus","url":"/pages/graphics-haus"},{"q":"What can I make in Graphics Haus?","a":"Clipart packs, cute seasonal animals, characters, retro object icons and other on-brand graphics you can sell or use in your products and marketing.","haus":"Graphics Haus","url":"/pages/graphics-haus"},{"q":"What is a Look Lock?","a":"A Look Lock saves a visual style so everything in a set stays consistent — same palette, mood and art direction — instead of drifting from image to image.","haus":"Graphics Haus","url":"/pages/graphics-haus"},{"q":"What does Project Haus do?","a":"Project Haus helps you turn an idea into a real, sellable digital product — invitations, devotional and motivation cards, journals, planners and more — step by step.","haus":"Project Haus","url":"/pages/project-haus"},{"q":"What can I build in Project Haus?","a":"Digital products people actually buy: invitations and stationery, devotional and motivational cards, and other printable or downloadable pieces built around your brand.","haus":"Project Haus","url":"/pages/project-haus"},{"q":"Do I need a finished product idea first?","a":"Not a finished one. Project Haus walks you from a rough concept to a defined, sellable product, so you can start even if you only have a direction.","haus":"Project Haus","url":"/pages/project-haus"},{"q":"How is Project Haus different from Graphics Haus?","a":"Graphics Haus makes the visuals; Project Haus assembles them into a finished, sellable product with the copy, structure and details a buyer expects.","haus":"Project Haus","url":"/pages/project-haus"},{"q":"What does Marketing Haus do?","a":"Marketing Haus creates the pieces that get you seen and sell your work: product mockups, social posts, ads, emails, and sales and listing copy — all tuned to your brand.","haus":"Marketing Haus","url":"/pages/marketing-haus"},{"q":"What can I make in Marketing Haus?","a":"Product mockups, social graphics and captions, ad copy, email campaigns, sales and listing copy, plus a testimonial formatter for polishing customer quotes.","haus":"Marketing Haus","url":"/pages/marketing-haus"},{"q":"Will my marketing match my brand voice?","a":"Yes — Marketing Haus pulls in your Brand Kit and Look Lock, so your posts, ads and emails sound and look like you across every channel.","haus":"Marketing Haus","url":"/pages/marketing-haus"},{"q":"Can Marketing Haus write my product listings?","a":"Yes — it generates SEO-minded listing and sales copy for your storefront, tuned to your product and audience.","haus":"Marketing Haus","url":"/pages/marketing-haus"},{"q":"What is the Testimonial Formatter?","a":"It turns raw customer feedback into clean, on-brand testimonial quotes and graphics you can drop straight into your marketing.","haus":"Marketing Haus","url":"/pages/marketing-haus"}];
